    px(c, x + 28, 14 + Math.sin(i) * 2, 8, 4, i % 2 ? 'rgba(255,200,74,.6)' : 'rgba(58,167,255,.6)');
  }
  // scoreboard screen
  px(c, 270, 10, 100, 26, '#05090f');
