  text(c, 'FINAL', 320, 31, 7, '#ffc84a', 'center', 'Press Start 2P');
  // floodlights
  for (const x of [48, 592]) {
    px(c, x - 5, -2, 10, 30, '#27364f');
    px(c, x - 30, -8, 60, 11, '#18253c');
    for (let i = 0; i < 5; i++) px(c, x - 26 + i * 12, -5, 8, 6, '#fff3c9');
    c.save();
    c.globalAlpha = .055;
    c.fillStyle = '#fff3c9';
    c.beginPath(); c.moveTo(x - 30, 4); c.lineTo(x + 30, 4); c.lineTo(x + 130, 330); c.lineTo(x - 130, 330); c.closePath(); c.fill();
    c.restore();
  }
  // side temporary stands
  px(c, 0, 74, FIELD.l, 260, '#13263f');
  px(c, FIELD.r, 74, W - FIELD.r, 260, '#13263f');
  paintCrowdBand(c, 0, 80, FIELD.l, 230, 31, ['#ffc84a', '#3ddc84', '#f7e8c8']);
  paintCrowdBand(c, FIELD.r, 80, W - FIELD.r, 230, 47, ['#3aa7ff', '#f7e8c8', '#1d5fd1']);
  paintPitch(c, 'final');
  paintCornerFlags(c, '#ffc84a');
  // bottom boards
  px(c, 0, 320, W, 22, '#07101e');
  const ads = [['WORLD YOUTH', '#f7e8c8', '#0a0e19'], ['SAMBA COLA', '#ffc84a', '#0a0e19'], ['BRASIL', '#3ddc84', '#0a0e19'], ['JAPÃO', '#3aa7ff', '#f7e8c8']];
  for (let i = 0; i < 4; i++) {
    const [label, bg, fg] = ads[i];
    px(c, 4 + i * 160, 324, 152, 14, bg);
    text(c, label, 80 + i * 160, 335, 6, fg, 'center', 'Press Start 2P');
  }
  px(c, 0, 342, W, 18, '#040810');
  text(c, 'TOKYO NATIONAL STADIUM', 320, 355, 6, 'rgba(247,232,200,.3)', 'center', 'Press Start 2P');
}

function paintCrowdBand(c, x, y, w, h, seed, colors) {
  const rnd = mulberry32(seed);
  px(c, x, y, w, h, '#0b1220');
  for (let row = 0; row < Math.floor(h / 6); row++) {
    for (let i = 0; i < Math.floor(w / 4); i++) {
      const xx = x + i * 4 + (row % 2) * 2;
      const yy = y + row * 6;
      if (rnd() > .35) px(c, xx, yy + rnd() * 3, 2, 2, colors[Math.floor(rnd() * colors.length)]);
    }
  }
  // tier rails
  for (let row = 0; row < 3; row++) px(c, x, y + 16 + row * 17, w, 2, 'rgba(255,255,255,.07)');
}

function paintPitch(c, kind) {
  const pal = kind === 'street'
    ? { a: '#c49a60', b: '#cfa96e', c: '#b78c54', line: 'rgba(250,244,220,.72)', side: '#b4864f' }
    : kind === 'final'
      ? { a: '#1c6a47', b: '#227852', c: '#185d3d', line: 'rgba(245,255,248,.9)', side: '#155639' }
      : { a: '#278456', b: '#2e9260', c: '#21744a', line: 'rgba(245,255,248,.82)', side: '#1d6a47' };

  // pitch
  px(c, FIELD.l, FIELD.t, PW, PH, pal.a);
  const stripe = PW / 8;
  for (let i = 0; i < 8; i++) {
    if (i % 2) px(c, FIELD.l + i * stripe, FIELD.t, stripe + 1, PH, pal.b);
  }
  // lighting from top
  const grad = c.createLinearGradient(0, FIELD.t, 0, FIELD.b);
  grad.addColorStop(0, 'rgba(0,0,0,.16)');
  grad.addColorStop(.45, 'rgba(255,255,255,.03)');
  grad.addColorStop(1, 'rgba(0,0,0,.08)');
  c.fillStyle = grad; c.fillRect(FIELD.l, FIELD.t, PW, PH);
  // speckles
  const rnd = mulberry32(kind === 'street' ? 17 : 29);
  for (let i = 0; i < 260; i++) {
    const x = FIELD.l + rnd() * PW, y = FIELD.t + rnd() * PH;
    px(c, x, y, 1 + (i % 2), 1, i % 3 ? 'rgba(255,255,220,.07)' : 'rgba(0,0,0,.09)');
  }
  // worn patches
  for (let i = 0; i < 8; i++) {
    const x = FIELD.l + 40 + rnd() * (PW - 80);
    const y = FIELD.t + 30 + rnd() * (PH - 60);
    px(c, x, y, 12 + rnd() * 20, 2, 'rgba(0,0,0,.05)');
  }

  // lines
  c.save();
  c.strokeStyle = pal.line;
  c.lineWidth = 2;
  c.strokeRect(FIELD.l, FIELD.t, PW, PH);
  line(c, CENTER.x, FIELD.t, CENTER.x, FIELD.b, pal.line, 2);
  ring(c, CENTER.x, CENTER.y, 37, pal.line, 2);
  circle(c, CENTER.x, CENTER.y, 2.4, pal.line);
  // penalty boxes
  for (const side of [0, 1]) {
    const dir = side === 0 ? 1 : -1;
    const x = side === 0 ? FIELD.l : FIELD.r;
    const boxW = 62;
    const boxTop = CENTER.y - 43, boxH = 86;
    c.strokeRect(side === 0 ? x : x - boxW, boxTop, boxW, boxH);
    const sixW = 26;
    c.strokeRect(side === 0 ? x : x - sixW, CENTER.y - 21, sixW, 42);
    const spotX = side === 0 ? x + 43 : x - 43;
    circle(c, spotX, CENTER.y, 1.8, pal.line);
    // arc
    c.beginPath();
    c.arc(spotX, CENTER.y, 23, side === 0 ? -Math.PI * .42 : Math.PI * .58, side === 0 ? Math.PI * .42 : Math.PI * 1.42);
    c.stroke();
  }
  // corner arcs
  for (const [x, y] of [[FIELD.l, FIELD.t], [FIELD.r, FIELD.t], [FIELD.l, FIELD.b], [FIELD.r, FIELD.b]]) {
    c.beginPath();
    c.arc(x, y, 10, 0, Math.PI * 2);
    c.stroke();
  }
  c.restore();

  // goal nets
  drawGoal(c, 'left', kind);
  drawGoal(c, 'right', kind);

  // center watermark
  if (kind === 'final') {
    c.save();
    c.globalAlpha = .08;
    text(c, '10', CENTER.x, CENTER.y + 9, 30, '#ffc84a', 'center', 'Press Start 2P');
    c.restore();
  }
}

function drawGoal(c, side, kind) {
  const left = side === 'left';
  const x = left ? FIELD.l : FIELD.r;
  const nx = left ? x - GOAL.depth : x;
  const w = GOAL.depth;
  const top = GOAL.top, bottom = GOAL.bottom;
  // net backing
  px(c, nx, top, w, bottom - top, kind === 'street' ? 'rgba(30,22,18,.55)' : 'rgba(5,12,18,.6)');
  const netCol = kind === 'street' ? 'rgba(240,220,180,.36)' : 'rgba(235,245,255,.34)';
  for (let y = top + 4; y < bottom; y += 5) line(c, nx, y, x, y, netCol, 1);
  for (let xx = nx + 3; xx < x; xx += 5) line(c, xx, top, xx, bottom, netCol, 1);
  // posts
  px(c, left ? x - 1 : x - 1, top - 2, 3, 4, '#f0f6ff');
  px(c, left ? x - 1 : x - 1, bottom - 2, 3, 4, '#f0f6ff');
  line(c, nx, top, x, top, '#e7f0ff', 2);
  line(c, nx, bottom, x, bottom, '#e7f0ff', 2);
  line(c, nx, top, nx, bottom, 'rgba(230,240,255,.5)', 1);
  // goal shadow
  c.fillStyle = 'rgba(0,0,0,.18)';
  c.beginPath(); c.ellipse(left ? x + 5 : x - 5, CENTER.y, 9, 35, 0, 0, Math.PI * 2); c.fill();
}

function paintCornerFlags(c, color) {
  const corners = [[FIELD.l, FIELD.t], [FIELD.r, FIELD.t], [FIELD.l, FIELD.b], [FIELD.r, FIELD.b]];
  for (const [x, y] of corners) {
    px(c, x - 1, y - 8, 2, 10, '#e8e0cc');
    px(c, x, y - 8, 8, 5, color);
    c.fillStyle = color;
    c.beginPath(); c.moveTo(x + 8, y - 8); c.lineTo(x + 8, y - 3); c.lineTo(x + 12, y - 5); c.closePath(); c.fill();
  }
}

function paintPalmSilhouette(c, x, ground, s, color) {
  let xx = x;
  for (let i = 0; i < 7; i++) {
    px(c, xx, ground - i * 12 * s, 4 * s, 13 * s, color);
    xx += 1.4 * s;
  }
  for (let i = 0; i < 6; i++) {
    const a = -Math.PI * .9 + i * .33;
    for (let j = 0; j < 8; j++) {
      px(c, xx + Math.cos(a) * j * 5 * s, ground - 84 * s + Math.sin(a) * j * 5 * s, 2, 2, color);
    }
  }
}

/* ------------------------------------------------------------------ */
/* PLAYERS                                                             */
/* ------------------------------------------------------------------ */

const SKINS = ['#7a4a2b', '#a06a42', '#c98f62', '#8a5a35', '#6b3f24', '#d7a77c', '#b07a52'];
const HAIRS = ['#17100e', '#241a14', '#2b1a10', '#1a1a24', '#3a2518'];

export function drawPlayer(c, p, t, opts = {}) {
  const scale = opts.scale || 1;
  const x = p.x, y = p.y;
  const team = p.team;
  const gk = p.role === 'GK';
  const jersey = p.kit ? p.kit.color : (team === 0 ? '#ffc84a' : '#ff5d6c');
  const accent = p.kit ? p.kit.accent : (team === 0 ? '#00a86b' : '#1a1a24');
  const shorts = gk ? '#141b2a' : (team === 0 ? '#1d5fd1' : accent);
  const skin = p.skin || SKINS[(p.num || 0) % SKINS.length];
  const hair = p.hair || HAIRS[(p.num || 0) % HAIRS.length];
  const speed = p.speed || Math.hypot(p.vx || 0, p.vy || 0);
  const run = Math.sin((p.anim || 0) * 14 + (p.num || 0));
  const moving = speed > 6;
  const facing = p.facing || (p.vx < -2 ? -1 : 1);
  const bob = moving ? Math.abs(Math.sin((p.anim || 0) * 14)) : Math.sin((t || 0) * 2 + (p.num || 0)) * .4;
  const celeb = p.celebrate;

  c.save();
  c.translate(Math.round(x), Math.round(y));
  if (scale !== 1) c.scale(scale, scale);

  // shadow
  c.fillStyle = 'rgba(0,0,0,.26)';
  c.beginPath(); c.ellipse(0, 1, 7.2, 2.4, 0, 0, Math.PI * 2); c.fill();

  // aura
  if (p.aura && !opts.noUi) {
    c.globalAlpha = .2 + Math.sin((t || 0) * 4) * .07;
    circle(c, 0, -14, 20, '#ffc84a');
    c.globalAlpha = 1;
  }

  // legs
  const swing = moving ? run * 3 : 0;
  if (!celeb) {
    px(c, -4, -9, 3, 7 + swing, skin);
    px(c, 1, -9, 3, 7 - swing, skin);
    px(c, -5, -3 + swing, 4, 3, '#15151d');
    px(c, 1, -3 - swing, 4, 3, '#15151d');
    // socks
    px(c, -4, -6, 3, 3, '#f1ead9');
    px(c, 1, -6, 3, 3, '#f1ead9');
  } else {
    px(c, -4, -9, 3, 8, skin);
    px(c, 1, -9, 3, 8, skin);
    px(c, -5, -2, 4, 3, '#15151d');
    px(c, 1, -2, 4, 3, '#15151d');
  }

  // shorts
  px(c, -5, -12 - bob, 10, 4, shorts);
  px(c, -5, -12 - bob, 10, 1, 'rgba(255,255,255,.15)');

  // torso
  px(c, -6, -21 - bob, 12, 9, jersey);
  px(c, -6, -21 - bob, 12, 1, 'rgba(255,255,255,.22)');
  px(c, -6, -15 - bob, 12, 1, accent);
  // sleeve cuffs
  px(c, -7, -20 - bob, 2, 4, accent);
  px(c, 5, -20 - bob, 2, 4, accent);
  // arms
  const armSwing = moving ? run * 2 : 0;
  px(c, -8, -20 - bob + armSwing, 2, 7, skin);
  px(c, 6, -20 - bob - armSwing, 2, 7, skin);
  if (gk) {
    px(c, -9, -14 - bob + armSwing, 3, 3, '#f7e8c8');
    px(c, 6, -14 - bob - armSwing, 3, 3, '#f7e8c8');
  }

  // head
  px(c, -4, -29 - bob, 8, 8, skin);
  px(c, -4, -29 - bob, 8, 1, 'rgba(255,255,255,.08)');
  // ears
  px(c, -5, -26 - bob, 1, 2, skin);
  px(c, 4, -26 - bob, 1, 2, skin);
  // eye
  if (facing >= 0) px(c, 2, -26 - bob, 1, 2, '#151019');
  else px(c, -3, -26 - bob, 1, 2, '#151019');
  // mouth
  px(c, facing >= 0 ? 2 : -3, -24 - bob, 2, 1, 'rgba(50,20,20,.55)');

  // hair
  if (p.isUser) {
    px(c, -4, -30 - bob, 8, 3, '#17100e');
    px(c, -5, -29 - bob, 1, 3, '#17100e');
    px(c, 4, -29 - bob, 1, 3, '#17100e');
    // curls
    circle(c, -4, -30 - bob, 1.6, '#17100e');
    circle(c, -1, -31 - bob, 1.8, '#17100e');
    circle(c, 2, -31 - bob, 1.8, '#17100e');
    circle(c, 4, -29 - bob, 1.5, '#17100e');
    // headband
    px(c, -4, -27.4 - bob, 8, 1.6, '#ffc84a');
    px(c, 4, -27 - bob, 1, 1, '#ffc84a');
  } else if (gk) {
    px(c, -4, -30 - bob, 8, 3, '#1a1a24');
    px(c, -5, -28 - bob, 1, 2, '#1a1a24');
    px(c, 4, -28 - bob, 1, 2, '#1a1a24');
  } else if ((p.num || 0) % 3 === 0) {
    px(c, -4, -30 - bob, 8, 2, hair);
    px(c, -5, -28 - bob, 1, 2, hair);
    px(c, 4, -28 - bob, 1, 2, hair);
  } else if ((p.num || 0) % 3 === 1) {
    px(c, -4, -30 - bob, 8, 3, hair);
    px(c, -5, -27 - bob, 1, 1, hair);
    px(c, 4, -27 - bob, 1, 1, hair);
  } else {
    px(c, -4, -30 - bob, 8, 2, hair);
    px(c, -4, -28 - bob, 8, 1, hair);
  }

  // tiny number / captain mark
  if (p.isUser) {
    px(c, -1, -19 - bob, 2, 1, '#0a0e19');
    px(c, -1, -17 - bob, 2, 1, '#0a0e19');
  }

  // selection marker
  if (p.isUser && !opts.noUi) {
    const pulse = .5 + Math.sin((t || 0) * 5) * .2;
    c.globalAlpha = .35 + pulse * .25;
    ring(c, 0, 1, 10.5, '#ffc84a', 1.5);
    c.globalAlpha = 1;
    // chevron
    const oy = -38 - bob + Math.sin((t || 0) * 4) * 1.2;
    c.fillStyle = '#ffc84a';
    c.beginPath(); c.moveTo(0, oy); c.lineTo(-3, oy - 4); c.lineTo(3, oy - 4); c.closePath(); c.fill();
    // name tag
    if (opts.tag !== false) {
      px(c, -17, oy - 12, 34, 7, 'rgba(8,13,25,.82)');
      text(c, 'CARLOS 10', 0, oy - 6, 5, '#ffc84a', 'center');
    }
  }

  // stun stars
  if (p.stun > 0) {
    for (let i = 0; i < 3; i++) {
      const a = (t || 0) * 5 + i * 2.1;
      px(c, Math.cos(a) * 8, -33 - bob + Math.sin(a) * 2, 2, 2, '#ffe28a');
    }
  }

  // celebration arms
  if (celeb) {
    px(c, -8, -27 - bob, 2, 8, skin);
    px(c, 6, -27 - bob, 2, 8, skin);
  }

  c.restore();
}

export function drawBall(c, ball, t) {
  const x = Math.round(ball.x), y = Math.round(ball.y);
  // trail
  if (ball.trail && ball.trail.length) {
    for (let i = 0; i < ball.trail.length; i++) {
      const tr = ball.trail[i];
      const a = (i / ball.trail.length) * .32;
      circle(c, tr.x, tr.y, 1.5 + (i / ball.trail.length) * 2.2, ball.team === 0 ? `rgba(255,220,120,${a})` : `rgba(120,210,255,${a})`);
    }
  }
  // shadow
  c.fillStyle = 'rgba(0,0,0,.24)';
  c.beginPath(); c.ellipse(x + 1, y + 3, 4, 1.6, 0, 0, Math.PI * 2); c.fill();
  // ball
  circle(c, x, y, 3.6, '#f7f0df');
  circle(c, x, y, 3.6, 'rgba(255,255,255,.1)');
  const r = (ball.roll || 0);
  const spots = [[0, 0], [Math.cos(r) * 2, Math.sin(r) * 2], [Math.cos(r + 2.1) * 2, Math.sin(r + 2.1) * 2], [Math.cos(r + 4.2) * 2, Math.sin(r + 4.2) * 2]];
  for (let i = 0; i < spots.length; i++) {
    const [sx, sy] = spots[i];
    px(c, x + sx - .8, y + sy - .8, 1.6, 1.6, '#1c2333');
  }
  c.strokeStyle = 'rgba(20,25,40,.4)'; c.lineWidth = .8;
  c.beginPath(); c.arc(x, y, 3.6, 0, Math.PI * 2); c.stroke();
}

/* ------------------------------------------------------------------ */
/* MATCH PRESENTATION                                                  */
/* ------------------------------------------------------------------ */

export function drawMatchScene(c, match, t) {
  c.drawImage(getArenaBase(match.config.arena), 0, 0);
  drawArenaDynamic(c, match, t);

  if (match.cine) {
    drawCinematic(c, match, t);
    return;
  }

  // players sorted by feet y
  const players = [...match.home.players, ...match.away.players];
  players.sort((a, b) => a.y - b.y);
  for (const p of players) drawPlayer(c, p, t);

  // ball
  drawBall(c, match.ball, t);

  // charge ring + aim
  if (match.charge && match.charge.active) {
    const p = match.user;
    const q = match.charge.quality || 0;
    const col = q > .72 ? '#3ddc84' : q > .4 ? '#ffc84a' : '#ff5d6c';
    ring(c, p.x, p.y, 15 + Math.sin(t * 10) * 1.5, col, 1.5);
    c.globalAlpha = .8;
    line(c, p.x, p.y, 596, 196 + (match.charge.aimY || 0) * 26, col, 1);
    c.globalAlpha = .25;
    line(c, p.x, p.y - 1, 596, 196 + (match.charge.aimY || 0) * 26, col, 4);
    c.globalAlpha = 1;
  }

  // effects
  for (const fx of match.effects || []) {
    const a = clamp(fx.life / fx.max, 0, 1);
    if (fx.kind === 'confetti') {
      px(c, fx.x, fx.y, fx.size, fx.size * 1.6, fx.color);
    } else if (fx.kind === 'dust') {
      c.globalAlpha = a * .5;
      circle(c, fx.x, fx.y, fx.size * (1.4 - a * .4), fx.color);
      c.globalAlpha = 1;
    } else if (fx.kind === 'spark') {
      c.globalAlpha = a;
      line(c, fx.x, fx.y, fx.x - fx.vx * .04, fx.y - fx.vy * .04, fx.color, 1.4);
      c.globalAlpha = 1;
    } else if (fx.kind === 'text') {
      c.globalAlpha = a;
      text(c, fx.text, fx.x, fx.y, fx.size || 8, fx.color, 'center', 'Press Start 2P');
      c.globalAlpha = 1;
    }
  }

  // goal / halftime tints
  if (match.state === 'goal') {
    const flash = Math.max(0, 1 - match.stateT * 1.8);
    c.fillStyle = `rgba(255,255,255,${flash * .32})`;
    c.fillRect(0, 0, W, H);
    drawCelebrationConfetti(c, match, t);
  }

  if (match.tension >= 100) {
    const p = match.user;
    c.globalAlpha = .1 + Math.sin(t * 6) * .05;
    circle(c, p.x, p.y - 12, 26, '#ffc84a');
    c.globalAlpha = 1;
  }

  // final flash
  if (match.flash > 0) {
    c.fillStyle = `rgba(255,255,255,${clamp(match.flash, 0, .7)})`;
    c.fillRect(0, 0, W, H);
  }
}

function drawArenaDynamic(c, match, t) {
  const arena = match.config.arena;
  const rnd = mulberry32(arena === 'final' ? 71 : arena === 'club' ? 41 : 23);
  const standH = 74;
  // crowd flashes
  for (let i = 0; i < 10; i++) {
    const x = rnd() * W;
    const y = 10 + rnd() * 52;
    const on = Math.sin(t * (1.5 + i * .35) + i * 2.7) > .94;
    if (on) px(c, x, y, 2, 2, 'rgba(255,255,255,.95)');
  }
  // flags
  for (let i = 0; i < 5; i++) {
    const x = 24 + i * 140;
    const y = 20 + (i % 2) * 8;
    const wav = Math.sin(t * 2.4 + i) * 2;
    px(c, x, y, 20, 8, i % 2 ? (arena === 'final' ? '#ffc84a' : '#3aa7ff') : (arena === 'final' ? '#3ddc84' : '#ffc84a'));
    px(c, x + 20, y + wav, 7, 3, i % 2 ? (arena === 'final' ? '#ffc84a' : '#3aa7ff') : (arena === 'final' ? '#3ddc84' : '#ffc84a'));
  }
  // corner flags wave
  if (Math.sin(t * 3) > 0) {
    px(c, FIELD.r + 1, FIELD.t - 8, 7, 4, '#ffc84a');
  }
  // ambient confetti at final
  if (arena === 'final') {
    for (let i = 0; i < 18; i++) {
      const x = (i * 41 + t * 9) % W;
      const y = (i * 29 + t * 18) % H;
      px(c, x, y, 1, 2, ['#ffc84a', '#3ddc84', '#3aa7ff', '#ff5d6c', '#f7e8c8'][i % 5]);
    }
  }
  // light beams
  if (arena === 'final') {
    c.save();
    c.globalAlpha = .05 + Math.sin(t * .7) * .012;
    c.fillStyle = '#fff4cf';
    c.beginPath(); c.moveTo(48, 8); c.lineTo(92, 8); c.lineTo(190, 320); c.lineTo(20, 320); c.closePath(); c.fill();
    c.beginPath(); c.moveTo(548, 8); c.lineTo(592, 8); c.lineTo(622, 320); c.lineTo(452, 320); c.closePath(); c.fill();
    c.restore();
  }
  // ball shadow on field? ball handles
}

function drawCelebrationConfetti(c, match, t) {
  const col = match.lastGoalTeam === 0 ? ['#ffc84a', '#3ddc84', '#f7e8c8'] : ['#3aa7ff', '#f7e8c8', '#ff5d6c'];
  for (let i = 0; i < 90; i++) {
    const x = (i * 73 + Math.sin(t * 3 + i) * 18 + t * 30) % W;
    const y = (i * 37 + t * 65 + Math.sin(t * 2 + i) * 20) % H;
    px(c, x, y, 2, 3, col[i % col.length]);
  }
  // golden glow
  c.save();
  c.globalAlpha = .12;
  circle(c, match.user.x, match.user.y - 10, 50, '#ffc84a');
  c.restore();
}

/* ------------------------------------------------------------------ */
/* TRAINING VIEW                                                       */
/* ------------------------------------------------------------------ */

export function drawTrainingView(c, data, t) {
  drawScene(c, data.scene || 'beach_sunset', t);
  // vignette + bottom scrim
  const grad = c.createLinearGradient(0, 180, 0, 360);
  grad.addColorStop(0, 'rgba(5,8,16,0)');
  grad.addColorStop(1, 'rgba(5,8,16,.72)');
  c.fillStyle = grad; c.fillRect(0, 180, W, 180);

  const bx = 320;
  const ground = 306;
  // spotlight
  c.save();
  c.globalAlpha = .1 + Math.sin(t * 2) * .025;
  circle(c, bx, ground - 30, 90, '#fff1c2');
  c.restore();

  // coach silhouette
  drawCoach(c, 468, 312, t);

  // Carlos juggling
  const fake = {
    x: bx, y: ground, vx: 0, vy: 0, num: 10, team: 0, role: 'FW', isUser: true,
    kit: { color: '#ffc84a', accent: '#00a86b' }, anim: t,
    facing: 1, speed: 0
  };
  drawPlayer(c, fake, t, { scale: 1.75, tag: false });

  // ball arc
  const hp = data.ballHeight || 0;
  const ballY = ground - 48 - hp * 82;
  const ballX = bx + 6 + Math.sin(t * 4) * 8;
  circle(c, ballX, ground - 8, 8, 'rgba(255,240,180,.05)');
  circle(c, ballX, ballY, 6, '#f7f0df');
  circle(c, ballX, ballY, 6, 'rgba(255,255,255,.08)');
  px(c, ballX - 2, ballY - 2, 4, 4, '#1c2333');
  px(c, ballX - 3, ballY + 3, 2, 2, '#1c2333');
  // trail
  for (let i = 1; i < 5; i++) {
    circle(c, ballX - i * .6, ballY + i * 4, 4.5 - i * .6, `rgba(255,240,200,${.16 - i * .028})`);
  }
  // hit sparkle
  if (data.hitFlash > 0) {
    c.save();
    c.globalAlpha = clamp(data.hitFlash, 0, 1);
    for (let i = 0; i < 8; i++) {
      const a = i * Math.PI / 4;
      line(c, ballX, ballY, ballX + Math.cos(a) * 22, ballY + Math.sin(a) * 22, '#ffc84a', 2);
    }
    c.restore();
    text(c, data.hitText || 'NICE!', 320, 120, 14, '#ffc84a', 'center', 'Press Start 2P');
  }

  // pips
  for (let i = 0; i < (data.attempts || 8); i++) {
    const x = 268 + i * 15;
    circle(c, x, 82, 3, i < (data.hits || 0) ? '#ffc84a' : 'rgba(247,232,200,.18)');
  }
}

function drawCoach(c, x, y, t) {
  const col = 'rgba(18,14,22,.75)';
  px(c, x - 4, y - 24, 8, 8, col);
  px(c, x - 7, y - 16, 14, 12, col);
  px(c, x - 7, y - 4, 4, 6, col);
  px(c, x + 2, y - 4, 4, 6, col);
  px(c, x - 11, y - 17 + Math.sin(t * 3) * 2, 4, 9, col);
  px(c, x + 7, y - 17 - Math.sin(t * 3) * 2, 4, 9, col);
  // whistle
  px(c, x + 4, y - 12, 2, 2, '#ffc84a');
}

/* =========================================================
   CINEMATICS — oversized special-move illustrations
   ========================================================= */

import { W, H, px, circle, ring, line, text, clamp, lerp, mulberry32 } from './pixel.js';
import { drawPlayer } from './arena.js';

export function drawCinematic(c, match, t) {
  const cine = match.cine;
  const p = clamp(cine.t / cine.dur, 0, 1);
  const accent = cine.kind === 'drive' ? '#3aa7ff' : cine.kind === 'rotation' ? '#ffc84a' : cine.kind === 'samba' ? '#3ddc84' : '#ffc84a';

  // dark backdrop
  const grad = c.createLinearGradient(0, 0, 0, H);
  grad.addColorStop(0, '#04070f');
  grad.addColorStop(.55, '#0a1222');
  grad.addColorStop(1, '#050810');
  c.fillStyle = grad; c.fillRect(0, 0, W, H);

  // radial burning sky
  c.save();
  c.translate(W / 2, H / 2 + 10);
  c.rotate(t * .12);
  for (let i = 0; i < 30; i++) {
    const a = i * Math.PI * 2 / 30;
    c.fillStyle = `rgba(${accent === '#3aa7ff' ? '58,167,255' : '255,200,74'},${.018 + (i % 3) * .008})`;
    c.beginPath();
    c.moveTo(0, 0);
    c.lineTo(Math.cos(a) * 700, Math.sin(a) * 700);
    c.lineTo(Math.cos(a + .055) * 700, Math.sin(a + .055) * 700);
    c.closePath(); c.fill();
  }
  c.restore();

  // stadium silhouette
  px(c, 0, H - 46, W, 46, 'rgba(3,6,12,.85)');
  px(c, 0, H - 48, W, 3, 'rgba(255,255,255,.08)');
  for (let i = 0; i < 40; i++) {
    const x = (i * 37) % W;
    px(c, x, H - 38 - (i % 4) * 3, 2, 2, 'rgba(255,220,150,.25)');
  }
  // crowd flashes
  const rnd = mulberry32(41);
  for (let i = 0; i < 12; i++) {
    const x = rnd() * W, y = H - 44 + rnd() * 20;
    if (Math.sin(t * 5 + i) > .6) px(c, x, y, 2, 2, 'rgba(255,255,255,.8)');
  }

  if (cine.kind === 'rotation') drawRotation(c, match, cine, p, t);
  else if (cine.kind === 'samba') drawSamba(c, match, cine, p, t);
  else if (cine.kind === 'combi') drawCombi(c, match, cine, p, t);
  else if (cine.kind === 'drive') drawDrive(c, match, cine, p, t);
  else if (cine.kind === 'save') drawSave(c, match, cine, p, t);

  // letterbox
  px(c, 0, 0, W, 12, '#03050b');
  px(c, 0, H - 12, W, 12, '#03050b');
  px(c, 0, 12, W, 1, 'rgba(255,255,255,.09)');
  px(c, 0, H - 13, W, 1, 'rgba(255,255,255,.09)');

  // impact flash
  if (cine.kind === 'rotation') {
    const impact = 1 - Math.abs(p - .5) * 9;
    if (impact > 0) {
      c.fillStyle = `rgba(255,255,255,${clamp(impact, 0, .7) * .32})`;
      c.fillRect(0, 0, W, H);
    }
  }
  if (cine.kind === 'drive') {
    const impact = 1 - Math.abs(p - .78) * 10;
    if (impact > 0) {
      c.fillStyle = `rgba(180,225,255,${clamp(impact, 0, .8) * .42})`;
      c.fillRect(0, 0, W, H);
    }
  }

  // film grain
  for (let i = 0; i < 20; i++) {
    px(c, Math.random() * W, Math.random() * H, 1, 1, 'rgba(255,255,255,.05)');
  }
}

function fakePlayer(team, isUser, num) {
  return {
    x: 0, y: 0, vx: 8, vy: 0, num, team, role: isUser ? 'FW' : 'MF',
    isUser, kit: team === 0 ? { color: '#ffc84a', accent: '#00a86b' } : { color: '#3aa7ff', accent: '#f7e8c8' },
    anim: 0, facing: 1, speed: 8
  };
}

function bigCarlos(c, x, y, scale, t, opts = {}) {
  const p = fakePlayer(0, true, 10);
  p.x = x; p.y = y; p.anim = t;
  drawPlayer(c, p, t, { scale, noUi: true, tag: false });
}

function bigNando(c, x, y, scale, t) {
  const p = fakePlayer(0, false, 7);
  p.kit = { color: '#1d5fd1', accent: '#f7e8c8' };
  p.x = x; p.y = y; p.anim = t;
  drawPlayer(c, p, t, { scale, noUi: true, tag: false });
}

function bigTsubasa(c, x, y, scale, t) {
  const p = fakePlayer(1, false, 10);
  p.kit = { color: '#1f4fd1', accent: '#f7e8c8' };
  p.x = x; p.y = y; p.anim = t;
  drawPlayer(c, p, t, { scale, noUi: true, tag: false });
}

/* ------------------------------------------------------------------ */
/* SANTANA ROTATION                                                    */
/* ------------------------------------------------------------------ */

function drawRotation(c, match, cine, p, t) {
  // ground glow
  c.save();
  c.globalAlpha = .14;
  circle(c, 250, 286, 120, '#ffc84a');
  c.restore();

  // goal silhouette at right
  drawGoalSilhouette(c, 596, 196, 'right');

  const leap = Math.sin(clamp(p / .52, 0, 1) * Math.PI) * 44;
  const spin = p < .52 ? -(p / .52) * Math.PI * 2.3 : -Math.PI * 2.3;

  // after-images
  for (let i = 4; i >= 1; i--) {
    c.save();
    c.globalAlpha = .06 + i * .015;
    c.translate(250 + i * 8, 286 - leap * (1 - i * .07));
    c.rotate(spin * (1 - i * .12));
    bigCarlos(c, 0, 0, 4.1, t - i * .08);
    c.restore();
  }

  // main body
  c.save();
  c.translate(250, 286 - leap);
  c.rotate(spin);
  // aura
  c.globalAlpha = .16;
  circle(c, 0, -44, 76, '#ffc84a');
  c.globalAlpha = 1;
  bigCarlos(c, 0, 0, 4.1, t);
  c.restore();

  // ball at foot before impact
  const fx = 250, fy = 286 - leap - 18;
  if (p < .5) {
    circle(c, fx + 22 * Math.cos(spin), fy + 22 * Math.sin(spin), 9, '#f7f0df');
    circle(c, fx + 22 * Math.cos(spin), fy + 22 * Math.sin(spin), 9, 'rgba(255,255,255,.2)');
    px(c, fx + 22 * Math.cos(spin) - 3, fy + 22 * Math.sin(spin) - 2, 6, 5, '#1c2333');
  } else {
    // golden arc into the net
    const q = clamp((p - .5) / .44, 0, 1);
    const bx = lerp(282, 595, q);
    const by = lerp(250, 196, q) - Math.sin(q * Math.PI) * 82;
    // trail
    for (let i = 0; i < 22; i++) {
      const k = i / 22;
      const tx = lerp(282, bx, k);
      const ty = lerp(250, by, k) - Math.sin(k * Math.PI) * (82 * (bx - 282) / 313);
      circle(c, tx, ty, 2 + k * 7, `rgba(255,214,102,${.03 + k * .18})`);
    }
    // ball
    circle(c, bx, by, 9, '#fff5d6');
    circle(c, bx, by, 5, '#ffc84a');
    // net ripple
    if (q > .88) {
      for (let i = 0; i < 4; i++) ring(c, 596, 196, 10 + i * 9, `rgba(255,230,140,${.35 - i * .07})`, 2);
      circle(c, 596, 196, 20, 'rgba(255,255,255,.25)');
    }
  }

  // speed lines
  c.save();
  c.globalAlpha = .22;
  for (let i = 0; i < 12; i++) {
    const y = 40 + i * 25;
    line(c, 0, y, 60 + (i % 4) * 30, y - 3, '#ffc84a', 1);
    line(c, W, y + 8, W - 60 - (i % 3) * 30, y + 5, '#ffc84a', 1);
  }
  c.restore();

  // big caption shadow
  c.save();
  c.globalAlpha = .8;
  text(c, 'SANTANA', 250, 84, 12, '#ffc84a', 'center', 'Press Start 2P');
  text(c, 'ROTATION', 250, 100, 12, '#f7e8c8', 'center', 'Press Start 2P');
  c.restore();
}

function drawGoalSilhouette(c, x, y, side) {
  const left = side === 'left';
  const nx = left ? x - 18 : x;
  const top = y - 40, bottom = y + 40;
  px(c, nx, top, 18, 80, 'rgba(2,6,12,.7)');
  for (let yy = top; yy < bottom; yy += 6) line(c, nx, yy, x, yy, 'rgba(235,245,255,.28)', 1);
  for (let xx = nx; xx <= x; xx += 5) line(c, xx, top, xx, bottom, 'rgba(235,245,255,.22)', 1);
  line(c, x, top, x, top + 4, '#f0f6ff', 3);
  line(c, x, bottom, x, bottom - 4, '#f0f6ff', 3);
  line(c, nx, top, x, top, '#e7f0ff', 2);
  line(c, nx, bottom, x, bottom, '#e7f0ff', 2);
}

/* ------------------------------------------------------------------ */
/* SAMBA STEP                                                          */
/* ------------------------------------------------------------------ */

function drawSamba(c, match, cine, p, t) {
  // field ground
  px(c, 0, 270, W, 90, 'rgba(7,16,24,.65)');
  for (let i = 0; i < 10; i++) line(c, 0, 276 + i * 9, W, 276 + i * 9, 'rgba(255,255,255,.025)', 1);

  const speed = p * 180;
  // after-images trail
  for (let i = 4; i >= 0; i--) {
    c.save();
    c.globalAlpha = .1 + i * .05;
    bigCarlos(c, 100 + i * 52 + speed * .35, 292 - (i % 2) * 6, 3.1, t - i * .06);
    c.restore();
  }
  // main carlos
  bigCarlos(c, 100 + speed, 292, 3.1, t);

  // ball zig-zag
  for (let i = 0; i < 6; i++) {
    const k = (p * 1.4 + i * .16) % 1;
    const bx = 140 + k * 380;
    const by = 258 - Math.sin(k * Math.PI * 2) * 26;
    px(c, bx, by, 4, 4, i % 2 ? '#ffc84a' : '#f7f0df');
  }

  // defenders falling
  const defenders = [[300, 292, .5], [380, 286, .8], [455, 294, 1.05]];
  for (let i = 0; i < defenders.length; i++) {
    const [dx, dy, rot] = defenders[i];
    if (p > .25 + i * .16) {
      c.save();
      c.translate(dx, dy + Math.min(.25, p - .25 - i * .16) * 20);
      c.rotate(rot * Math.min(1, (p - .25 - i * .16) * 4));
      const fake = fakePlayer(1, false, i + 4);
      fake.kit = { color: i % 2 ? '#1d5fd1' : '#ff5d6c', accent: '#f7e8c8' };
      fake.x = 0; fake.y = 0; fake.anim = t;
      drawPlayer(c, fake, t, { scale: 2.4, noUi: true, tag: false });
      c.restore();
    }
  }

  // dust
  for (let i = 0; i < 16; i++) {
    circle(c, 120 + i * 28 + Math.sin(t + i) * 10, 300 - (i % 5) * 2, 3 + (i % 3), 'rgba(240,220,180,.11)');
  }

  c.save();
  c.globalAlpha = .85;
  text(c, 'SAMBA STEP', 320, 92, 13, '#ffc84a', 'center', 'Press Start 2P');
  c.restore();
}

/* ------------------------------------------------------------------ */
/* GOLDEN COMBI                                                        */
/* ------------------------------------------------------------------ */

function drawCombi(c, match, cine, p, t) {
  px(c, 0, 268, W, 92, 'rgba(6,14,22,.7)');
  for (let i = 0; i < 12; i++) line(c, 0, 274 + i * 8, W, 274 + i * 8, 'rgba(255,255,255,.025)', 1);

  bigCarlos(c, 150, 300, 3.3, t);
  bigNando(c, 465, 300, 3.1, t);

  // defender between
  c.save();
  c.globalAlpha = .8;
  const def = fakePlayer(1, false, 4);
  def.kit = { color: '#ff5d6c', accent: '#1a1a24' };
  def.x = 310; def.y = 300; def.anim = t;
  drawPlayer(c, def, t, { scale: 2.8, noUi: true, tag: false });
  c.restore();

  // ball path
  const phase = (p * 3) % 1;
  const startX = phase < .5 ? 190 : 420;
  const endX = phase < .5 ? 420 : 190;
  const bx = lerp(startX, endX, phase < .5 ? phase * 2 : (phase - .5) * 2);
  const by = 250 - Math.sin((phase < .5 ? phase * 2 : (phase - .5) * 2) * Math.PI) * 34;
  for (let i = 0; i < 16; i++) {
    const k = i / 16;
    const xx = lerp(startX, bx, k);
    const yy = lerp(250, by, k);
    circle(c, xx, yy, 1.5 + k * 2, `rgba(255,214,102,${.03 + k * .13})`);
  }
  circle(c, bx, by, 7, '#f7f0df');
  circle(c, bx, by, 4, '#ffc84a');

  // golden light path behind
  c.save();
  c.globalAlpha = .18;
  line(c, 190, 260, 420, 260, '#ffc84a', 4);
  line(c, 420, 260, 600, 220, '#ffc84a', 3);
  c.restore();

  // forward arrow after pass
  if (p > .55) {
    c.save();
    c.globalAlpha = clamp((p - .55) * 3, 0, .7);
    const ax = lerp(190, 600, clamp((p - .55) / .45, 0, 1));
    line(c, ax - 30, 244, ax, 228, '#ffc84a', 5);
    c.fillStyle = '#ffc84a';
    c.beginPath(); c.moveTo(ax + 8, 224); c.lineTo(ax - 8, 218); c.lineTo(ax - 4, 234); c.closePath(); c.fill();
    c.restore();
  }

  c.save();
  c.globalAlpha = .85;
  text(c, 'GOLDEN COMBI', 320, 92, 13, '#ffc84a', 'center', 'Press Start 2P');
  c.restore();
}

/* ------------------------------------------------------------------ */
/* TSUBASA'S DRIVE SHOT                                                */
/* ------------------------------------------------------------------ */

function drawDrive(c, match, cine, p, t) {
  // blue storm background
  c.save();
  c.globalAlpha = .18;
  for (let i = 0; i < 24; i++) {
    const y = 20 + i * 14;
    line(c, 0, y, W, y + 30, 'rgba(58,167,255,.32)', 1);
  }
  c.restore();

  // goal silhouette left
  drawGoalSilhouette(c, 44, 196, 'left');

  // giant Tsubasa
  bigTsubasa(c, 470, 306, 4.2, t);
  c.save();
  c.globalAlpha = .16 + Math.sin(t * 5) * .05;
  circle(c, 470, 232, 82, '#3aa7ff');
  c.restore();

  // charging ball
  if (p < .35) {
    const bx = 420, by = 250;
    circle(c, bx, by, 10 + Math.sin(t * 12) * 2, 'rgba(120,210,255,.4)');
    circle(c, bx, by, 6, '#e8f7ff');
    circle(c, bx, by, 3, '#3aa7ff');
  } else {
    const q = clamp((p - .35) / .5, 0, 1);
    const bx = lerp(420, 55, q);
    const by = lerp(246, 196, q) - Math.sin(q * Math.PI) * 64;
    for (let i = 0; i < 26; i++) {
      const k = i / 26;
      const tx = lerp(420, bx, k);
      const ty = lerp(246, by, k) - Math.sin(k * Math.PI) * (64 * (bx - 420) / -365);
      circle(c, tx, ty, 2 + k * 8, `rgba(78,180,255,${.02 + k * .17})`);
    }
    circle(c, bx, by, 10, '#dff4ff');
    circle(c, bx, by, 5, '#3aa7ff');
    // goalkeeper dive
    const gx = lerp(90, 62, q);
    const gy = 300 - q * 60;
    c.save();
    c.translate(gx, gy);
    c.rotate(-.7 * q);
    const gk = fakePlayer(0, false, 1);
    gk.role = 'GK';
    gk.kit = { color: '#3ddc84', accent: '#0a0e19' };
    gk.x = 0; gk.y = 0; gk.anim = t;
    drawPlayer(c, gk, t, { scale: 3.2, noUi: true, tag: false });
    c.restore();

    if (q > .9) {
      for (let i = 0; i < 4; i++) ring(c, 44, 196, 12 + i * 11, `rgba(120,215,255,${.4 - i * .08})`, 2);
      circle(c, 44, 196, 22, 'rgba(255,255,255,.28)');
    }
  }

  c.save();
  c.globalAlpha = .85;
  text(c, 'DRIVE SHOT', 320, 92, 13, '#3aa7ff', 'center', 'Press Start 2P');
  c.restore();
}

/* ------------------------------------------------------------------ */
/* BIG SAVE                                                            */
/* ------------------------------------------------------------------ */

function drawSave(c, match, cine, p, t) {
  drawGoalSilhouette(c, 44, 196, 'left');
  const q = clamp(p / .65, 0, 1);
  const gx = lerp(90, 52, q);
  const gy = 300 - q * 48;
  c.save();
  c.translate(gx, gy);
  c.rotate(-.8 * q);
  const gk = fakePlayer(0, false, 1);
  gk.role = 'GK';
  gk.kit = { color: '#3ddc84', accent: '#0a0e19' };
  gk.x = 0; gk.y = 0; gk.anim = t;
  drawPlayer(c, gk, t, { scale: 4, noUi: true, tag: false });
  c.restore();

  const bx = lerp(500, 48, clamp(p / .8, 0, 1));
  const by = lerp(250, 182, clamp(p / .8, 0, 1)) - Math.sin(clamp(p / .8, 0, 1) * Math.PI) * 38;
  circle(c, bx, by, 8, '#e8f7ff');
  circle(c, bx, by, 4, '#3aa7ff');
  for (let i = 0; i < 12; i++) {
    const k = i / 12;
    circle(c, lerp(500, bx, k), lerp(250, by, k), 1.5 + k * 4, `rgba(120,210,255,${.02 + k * .1})`);
  }
  if (p > .6) {
    c.save();
    c.globalAlpha = clamp((p - .6) * 4, 0, 1);
    text(c, 'SAVED!', 320, 110, 20, '#3ddc84', 'center', 'Press Start 2P');
    c.restore();
  }
}

/* =========================================================
   MATCH UI — HUD, duels, specials, pause, penalties
   ========================================================= */

import { drawPortrait } from './pixel.js';

const $ = (id) => document.getElementById(id);

export class MatchUI {
  constructor(callbacks = {}) {
    this.cb = callbacks;
    this.timers = new Set();
    this.toasts = [];
    this.bannerTimer = null;
    this.goalTimer = null;
    this.commentTimer = null;
    this.bound = [];
    this.el = {
      hud: $('match-hud'),
      score: $('sb-score'),
      home: $('sb-home'),
      away: $('sb-away'),
      clock: $('sb-clock'),
      half: $('sb-half'),
      commentary: $('commentary'),
      tensionWrap: $('tension-wrap'),
      tensionFill: $('tension-fill'),
      tensionValue: $('tension-value'),
      goalBanner: $('goal-banner'),
      goalSub: $('goal-sub'),
      pauseBtn: $('match-pause'),
      soundBtn: $('match-sound'),
      duel: $('duel'),
      duelTitle: $('duel-title'),
      duelContext: $('duel-context'),
      duelNameA: $('duel-name-a'),
      duelRoleA: $('duel-role-a'),
      duelNameB: $('duel-name-b'),
      duelRoleB: $('duel-role-b'),
      duelBarA: $('duel-bar-a'),
      duelBarB: $('duel-bar-b'),
      duelPortraitA: $('duel-portrait-a'),
      duelPortraitB: $('duel-portrait-b'),
      duelCommands: $('duel-commands'),
      duelMeterWrap: $('duel-meter-wrap'),
      duelMeter: $('duel-meter'),
      duelNeedle: $('duel-needle'),
      duelMeterHint: $('duel-meter-hint'),
      duelOutcome: $('duel-outcome'),
      special: $('special-menu'),
      specialEnergy: $('special-energy'),
      specialCards: $('special-cards'),
      specialClose: $('special-close'),
      pause: $('pause'),
      pauseTitle: $('pause-title'),
      pauseStats: $('pause-stats'),
      pauseResume: $('pause-resume'),
      pauseRestart: $('pause-restart'),
      pauseQuit: $('pause-quit'),
      penalty: $('penalty'),
      penaltyScore: $('penalty-score'),
      penaltyRound: $('penalty-round'),
      penaltyPrompt: $('penalty-prompt'),
      penaltyHint: $('penalty-hint'),
      penaltyBall: $('penalty-ball'),
      penaltyKeeper: $('penalty-keeper'),
      penaltyChoices: $('penalty-choices'),
      toastLayer: $('toast-layer'),
      banner: $('banner'),
      bannerKicker: $('banner-kicker'),
      bannerTitle: $('banner-title'),
      bannerSub: $('banner-sub')
    };
    this._bind();
  }

  _bind() {
    const on = (el, ev, fn) => {
      if (!el) return;
      el.addEventListener(ev, fn);
      this.bound.push([el, ev, fn]);
    };
    on(this.el.duelCommands, 'click', (e) => {
      const btn = e.target.closest('[data-cmd]');
      if (!btn || btn.disabled) return;
      this.cb.onDuelCommand?.(btn.dataset.cmd);
    });
    on(this.el.duelMeter, 'click', () => this.cb.onDuelLock?.());
    on(this.el.specialClose, 'click', () => this.cb.onSpecialClose?.());
    on(this.el.pauseBtn, 'click', () => this.cb.onPause?.());
    on(this.el.soundBtn, 'click', () => this.cb.onSound?.());
    on(this.el.pauseResume, 'click', () => this.cb.onResume?.());
    on(this.el.pauseRestart, 'click', () => this.cb.onRestart?.());
    on(this.el.pauseQuit, 'click', () => this.cb.onQuit?.());
    on(this.el.penaltyChoices, 'click', (e) => {
      const btn = e.target.closest('[data-penalty]');
      if (!btn || btn.disabled) return;
      this.cb.onPenalty?.(btn.dataset.penalty);
    });
  }

  delay(fn, ms) {
    const id = setTimeout(() => { this.timers.delete(id); fn(); }, ms);
    this.timers.add(id);
    return id;
  }

  setScreen(config) {
    const h = config.home, a = config.away;
    this.el.home.innerHTML = `<span class="sb-dot"></span><span class="sb-name">${h.short}</span>`;
    this.el.home.querySelector('.sb-dot').style.background = h.color;
    this.el.away.innerHTML = `<span class="sb-name">${a.short}</span><span class="sb-dot"></span>`;
    this.el.away.querySelector('.sb-dot').style.background = a.color;
    this.el.clock.textContent = "1'";
    this.el.half.textContent = '1ST HALF';
    this.el.tensionFill.style.width = '0%';
    this.el.tensionValue.textContent = '0';
    this.el.commentary.classList.remove('show');
    this.el.goalBanner.classList.remove('show');
    this.el.hud.hidden = false;
  }

  update(match) {
    this.el.score.innerHTML = `${match.score[0]} <i>:</i> ${match.score[1]}`;
    this.el.clock.textContent = match.clockLabel;
    this.el.half.textContent = match.halfLabel;
    const pct = Math.round(match.tension);
    this.el.tensionFill.style.width = `${pct}%`;
    this.el.tensionValue.textContent = pct;
    this.el.tensionWrap.classList.toggle('full', pct >= 100);
    if (match.commentaryT > 0) {
      this.el.commentary.classList.add('show');
    } else {
      this.el.commentary.classList.remove('show');
    }
  }

  say(speaker, text, duration = 3.4) {
    this.el.commentary.innerHTML = `<b>${speaker}</b> ${text}`;
    this.el.commentary.classList.add('show');
    if (this.commentTimer) clearTimeout(this.commentTimer);
    this.commentTimer = setTimeout(() => {
      this.el.commentary.classList.remove('show');
    }, duration * 1000);
    this.timers.add(this.commentTimer);
  }

  toast(text, kind = '') {
    const div = document.createElement('div');
    div.className = `toast ${kind}`;
    const [head, ...rest] = text.split('|');
    div.innerHTML = rest.length ? `<b>${head}</b><span>${rest.join('|')}</span>` : `<span>${head}</span>`;
    this.el.toastLayer.appendChild(div);
    this.toasts.push(div);
    while (this.toasts.length > 3) {
      const old = this.toasts.shift();
      old.remove();
    }
    this.delay(() => {
      div.classList.add('out');
      this.delay(() => div.remove(), 320);
      this.toasts = this.toasts.filter((x) => x !== div);
    }, 3000);
  }

  banner(kicker, title, sub, duration = 2600) {
    this.el.bannerKicker.textContent = kicker;
    this.el.bannerTitle.textContent = title;
    this.el.bannerSub.textContent = sub || '';
    this.el.banner.hidden = false;
    this.el.banner.classList.remove('out');
    void this.el.banner.offsetWidth;
    if (this.bannerTimer) clearTimeout(this.bannerTimer);
    this.bannerTimer = setTimeout(() => {
      this.el.banner.classList.add('out');
      this.delay(() => { this.el.banner.hidden = true; }, 320);
    }, duration);
    this.timers.add(this.bannerTimer);
  }

  goal(scorer, team) {
    this.el.goalSub.textContent = scorer || 'GOAL!';
    this.el.goalBanner.classList.remove('show');
    void this.el.goalBanner.offsetWidth;
    this.el.goalBanner.classList.add('show');
    this.el.goalBanner.style.filter = team === 1 ? 'hue-rotate(160deg)' : '';
    if (this.goalTimer) clearTimeout(this.goalTimer);
    this.goalTimer = setTimeout(() => this.el.goalBanner.classList.remove('show'), 2800);
    this.timers.add(this.goalTimer);
  }

  openDuel(match) {
    const d = match.duel;
    const atk = d.attacker;
    const def = d.defender;
    const attack = d.type === 'attack';
    this.el.duelTitle.textContent = attack ? 'MAKE SOMETHING HAPPEN' : 'WIN THE BALL BACK';
    this.el.duelContext.textContent = attack ? 'KEEP POSSESSION' : 'DEFENSIVE DUEL';
    this.el.duelNameA.textContent = atk.isUser ? 'CARLOS' : atk.name;
    this.el.duelRoleA.textContent = `${atk.role} · TECH ${atk.stats.technique}`;
    this.el.duelNameB.textContent = def.isUser ? 'CARLOS' : def.name;
    this.el.duelRoleB.textContent = `${def.role} · TECH ${def.stats.technique}`;
    this.el.duelBarA.style.width = `${clampPct(atk.stats.technique)}%`;
    this.el.duelBarB.style.width = `${clampPct(def.stats.technique)}%`;
    drawPortrait(this.el.duelPortraitA, atk.isUser ? 'carlos' : portraitFor(atk), attack ? 'intense' : 'stern');
    drawPortrait(this.el.duelPortraitB, def.isUser ? 'carlos' : portraitFor(def), 'intense');
    this.el.duelCommands.innerHTML = attack ? `
      <button type="button" class="duel-cmd" data-cmd="dribble"><span class="cmd-key">1</span><b>DRIBBLE</b><small>Technique</small></button>
      <button type="button" class="duel-cmd" data-cmd="pass"><span class="cmd-key">2</span><b>PASS</b><small>Find a friend</small></button>
      <button type="button" class="duel-cmd" data-cmd="shoot"><span class="cmd-key">3</span><b>SHOOT</b><small>Go for goal</small></button>
      <button type="button" class="duel-cmd special" data-cmd="special"><span class="cmd-key">4</span><b>SAMBA</b><small>${match.tension >= 20 ? '20 energy' : 'Need 20'}</small></button>
    ` : `
      <button type="button" class="duel-cmd" data-cmd="tackle"><span class="cmd-key">1</span><b>TACKLE</b><small>Power</small></button>
      <button type="button" class="duel-cmd" data-cmd="contain"><span class="cmd-key">2</span><b>CONTAIN</b><small>Stay close</small></button>
      <button type="button" class="duel-cmd" data-cmd="slide"><span class="cmd-key">3</span><b>SLIDE</b><small>Risk it</small></button>
      <button type="button" class="duel-cmd" data-cmd="special"><span class="cmd-key">4</span><b>SAMBA</b><small>${match.tension >= 20 ? '20 energy' : 'Need 20'}</small></button>
    `;
    if (attack) {
      const special = this.el.duelCommands.querySelector('[data-cmd="special"]');
      if (match.tension < 20) special.disabled = true;
      const shoot = this.el.duelCommands.querySelector('[data-cmd="shoot"]');
      if (!match.canShoot(atk)) shoot.disabled = true;
    } else {
      const special = this.el.duelCommands.querySelector('[data-cmd="special"]');
      if (match.tension < 20) special.disabled = true;
    }
    this.el.duelMeterWrap.hidden = true;
    this.el.duelOutcome.hidden = true;
    this.el.duel.hidden = false;
  }

  duelChoosePhase() {
    this.el.duelMeterWrap.hidden = false;
    this.el.duelOutcome.hidden = true;
    this.el.duelMeterHint.textContent = 'PRESS SPACE / TAP TO LOCK';
  }

  updateDuelMeter(value) {
    this.el.duelNeedle.style.left = `${value * 100}%`;
  }

  duelOutcome(text, bad = false) {
    this.el.duelOutcome.textContent = text;
    this.el.duelOutcome.hidden = false;
    this.el.duelOutcome.classList.toggle('bad', bad);
    this.el.duelMeterWrap.hidden = true;
  }

  closeDuel() {
    this.el.duel.hidden = true;
  }

  openSpecial(options, tension) {
    this.el.specialEnergy.textContent = Math.floor(tension);
    this.el.specialCards.innerHTML = options.map((o, i) => `
      <button type="button" class="special-card" data-special="${o.key}" ${o.enabled ? '' : 'disabled'}>
        <span class="sp-key">${i + 1}</span>
        <span class="sp-cost ${o.enabled ? '' : 'short'}">${o.cost} SAMBA</span>
        <span class="sp-icon">${o.icon}</span>
        <h3>${o.name}</h3>
        <p>${o.desc}${o.reason ? `<br><em>${o.reason}</em>` : ''}</p>
      </button>
    `).join('');
    this.el.specialCards.querySelectorAll('[data-special]').forEach((btn) => {
      btn.addEventListener('click', () => {
        if (!btn.disabled) this.cb.onSpecial?.(btn.dataset.special);
      });
    });
    this.el.special.hidden = false;
  }

  closeSpecial() {
    this.el.special.hidden = true;
  }

  openPause(match) {
    this.el.pauseTitle.textContent = match.config.venue;
    const poss = match.possessionPct();
    this.el.pauseStats.innerHTML = `
      <div class="pause-stat">SCORE<b>${match.score[0]} – ${match.score[1]}</b></div>
      <div class="pause-stat">POSSESSION<b>${poss[0]}% – ${poss[1]}%</b></div>
      <div class="pause-stat">SHOTS<b>${match.stats.shots[0]} – ${match.stats.shots[1]}</b></div>
      <div class="pause-stat">SAMBA<b>${Math.floor(match.tension)} / 100</b></div>
    `;
    this.el.pause.hidden = false;
  }

  closePause() {
    this.el.pause.hidden = true;
  }

  openPenalty() {
    this.el.penalty.hidden = false;
    this.resetPenaltyStage();
  }

  resetPenaltyStage() {
    this.el.penaltyBall.className = 'penalty-ball';
    this.el.penaltyKeeper.className = 'penalty-keeper';
    this.el.penaltyChoices.querySelectorAll('button').forEach((b) => { b.disabled = false; });
  }

  setPenalty(state) {
    this.el.penaltyScore.innerHTML = `${state.home} <span>–</span> ${state.away}`;
    this.el.penaltyRound.textContent = `ROUND ${state.round} · ${state.turn === 'home' ? 'BRASIL' : 'JAPÃO'}`;
    this.el.penaltyPrompt.textContent = state.phase === 'dive' ? 'PICK YOUR DIVE' : 'PICK YOUR CORNER';
    this.el.penaltyHint.textContent = state.message || 'THE STORY NEEDS A WINNER';
    this.el.penaltyChoices.querySelectorAll('button').forEach((b) => { b.disabled = state.animating; });
    this.resetPenaltyStage();
  }

  animatePenalty(dir, keeperDir, saved, isDive) {
    this.resetPenaltyStage();
    this.el.penaltyChoices.querySelectorAll('button').forEach((b) => { b.disabled = true; });
    // force reflow for CSS transition
    void this.el.penaltyBall.offsetWidth;
    const ballDir = dir === 'left' ? 'kick-left' : dir === 'right' ? 'kick-right' : 'kick-center';
    this.el.penaltyBall.classList.add(ballDir);
    if (saved) this.el.penaltyBall.classList.add('saved');
    this.el.penaltyKeeper.classList.add(`dive-${keeperDir}`);
    return saved;
  }

  penaltyResult(text) {
    this.el.penaltyPrompt.textContent = text;
    this.el.penaltyHint.textContent = 'GET READY...';
  }

  closePenalty() {
    this.el.penalty.hidden = true;
  }

  destroy() {
    for (const [el, ev, fn] of this.bound) el.removeEventListener(ev, fn);
    this.bound = [];
    for (const id of this.timers) clearTimeout(id);
    this.timers.clear();
    for (const t of this.toasts) t.remove();
    this.toasts = [];
    this.el.hud.hidden = true;
    this.el.duel.hidden = true;
    this.el.special.hidden = true;
    this.el.pause.hidden = true;
    this.el.penalty.hidden = true;
    this.el.banner.hidden = true;
    this.el.goalBanner.classList.remove('show');
    this.el.commentary.classList.remove('show');
    this.el.toastLayer.innerHTML = '';
  }
}

function clampPct(v) { return Math.max(5, Math.min(100, v)); }
function portraitFor(p) {
  if (p.portrait) return p.portrait;
  const n = (p.name || '').toUpperCase();
  if (n.includes('RATINHO')) return 'ratinho';
  if (n.includes('ROJAS')) return 'rojas';
  if (n.includes('TSUBASA')) return 'tsubasa';
  if (n.includes('NANDO')) return 'nando';
  if (n.includes('HYUGA')) return 'hyuga';
  if (n.includes('MISUGI')) return 'misugi';
  if (n.includes('VIDAL')) return 'vidal';
  return p.team === 0 ? 'nando' : 'ratinho';
}

