221:     const x = FIELD.l + 40 + rnd() * (PW - 80);
222:     const y = FIELD.t + 30 + rnd() * (PH - 60);
223:     px(c, x, y, 12 + rnd() * 20, 2, 'rgba(0,0,0,.05)');
224:   }
225: 
226:   // lines
227:   c.save();
228:   c.strokeStyle = pal.line;
229:   c.lineWidth = 2;
230:   c.strokeRect(FIELD.l, FIELD.t, PW, PH);
231:   line(c, CENTER.x, FIELD.t, CENTER.x, FIELD.b, pal.line, 2);
232:   ring(c, CENTER.x, CENTER.y, 37, pal.line, 2);
233:   circle(c, CENTER.x, CENTER.y, 2.4, pal.line);
234:   // penalty boxes
235:   for (const side of [0, 1]) {
236:     const dir = side === 0 ? 1 : -1;
237:     const x = side === 0 ? FIELD.l : FIELD.r;
238:     const boxW = 62;
239:     const boxTop = CENTER.y - 43, boxH = 86;
240:     c.strokeRect(side === 0 ? x : x - boxW, boxTop, boxW, boxH);
241:     const sixW = 26;
242:     c.strokeRect(side === 0 ? x : x - sixW, CENTER.y - 21, sixW, 42);
243:     const spotX = side === 0 ? x + 43 : x - 43;
244:     circle(c, spotX, CENTER.y, 1.8, pal.line);
245:     // arc
246:     c.beginPath();
247:     c.arc(spotX, CENTER.y, 23, side === 0 ? -Math.PI * .42 : Math.PI * .58, side === 0 ? Math.PI * .42 : Math.PI * 1.42);
248:     c.stroke();
249:   }
250:   // corner arcs
251:   for (const [x, y] of [[FIELD.l, FIELD.t], [FIELD.r, FIELD.t], [FIELD.l, FIELD.b], [FIELD.r, FIELD.b]]) {
252:     c.beginPath();
253:     c.arc(x, y, 10, 0, Math.PI * 2);
254:     c.stroke();
255:   }
256:   c.restore();
257: 
258:   // goal nets
259:   drawGoal(c, 'left', kind);
260:   drawGoal(c, 'right', kind);
261: 
262:   // center watermark
263:   if (kind === 'final') {
264:     c.save();
265:     c.globalAlpha = .08;
266:     text(c, '10', CENTER.x, CENTER.y + 9, 30, '#ffc84a', 'center', 'Press Start 2P');
267:     c.restore();
268:   }
