271: function drawGoal(c, side, kind) {
272:   const left = side === 'left';
273:   const x = left ? FIELD.l : FIELD.r;
274:   const nx = left ? x - GOAL.depth : x;
275:   const w = GOAL.depth;
276:   const top = GOAL.top, bottom = GOAL.bottom;
277:   // net backing
278:   px(c, nx, top, w, bottom - top, kind === 'street' ? 'rgba(30,22,18,.55)' : 'rgba(5,12,18,.6)');
279:   const netCol = kind === 'street' ? 'rgba(240,220,180,.36)' : 'rgba(235,245,255,.34)';
280:   for (let y = top + 4; y < bottom; y += 5) line(c, nx, y, x, y, netCol, 1);
281:   for (let xx = nx + 3; xx < x; xx += 5) line(c, xx, top, xx, bottom, netCol, 1);
282:   // posts
283:   px(c, left ? x - 1 : x - 1, top - 2, 3, 4, '#f0f6ff');
284:   px(c, left ? x - 1 : x - 1, bottom - 2, 3, 4, '#f0f6ff');
285:   line(c, nx, top, x, top, '#e7f0ff', 2);
286:   line(c, nx, bottom, x, bottom, '#e7f0ff', 2);
287:   line(c, nx, top, nx, bottom, 'rgba(230,240,255,.5)', 1);
288:   // goal shadow
289:   c.fillStyle = 'rgba(0,0,0,.18)';
290:   c.beginPath(); c.ellipse(left ? x + 5 : x - 5, CENTER.y, 9, 35, 0, 0, Math.PI * 2); c.fill();
291: }
