321: const SKINS = ['#7a4a2b', '#a06a42', '#c98f62', '#8a5a35', '#6b3f24', '#d7a77c', '#b07a52'];
322: const HAIRS = ['#17100e', '#241a14', '#2b1a10', '#1a1a24', '#3a2518'];
