324: export function drawPlayer(c, p, t, opts = {}) {
325:   const scale = opts.scale || 1;
326:   const x = p.x, y = p.y;
327:   const team = p.team;
328:   const gk = p.role === 'GK';
329:   const jersey = p.kit ? p.kit.color : (team === 0 ? '#ffc84a' : '#ff5d6c');
330:   const accent = p.kit ? p.kit.accent : (team === 0 ? '#00a86b' : '#1a1a24');
331:   const shorts = gk ? '#141b2a' : (team === 0 ? '#1d5fd1' : accent);
332:   const skin = p.skin || SKINS[(p.num || 0) % SKINS.length];
333:   const hair = p.hair || HAIRS[(p.num || 0) % HAIRS.length];
334:   const speed = p.speed || Math.hypot(p.vx || 0, p.vy || 0);
335:   const run = Math.sin((p.anim || 0) * 14 + (p.num || 0));
336:   const moving = speed > 6;
337:   const facing = p.facing || (p.vx < -2 ? -1 : 1);
338:   const bob = moving ? Math.abs(Math.sin((p.anim || 0) * 14)) : Math.sin((t || 0) * 2 + (p.num || 0)) * .4;
339:   const celeb = p.celebrate;
340: 
341:   c.save();
342:   c.translate(Math.round(x), Math.round(y));
343:   if (scale !== 1) c.scale(scale, scale);
344: 
345:   // shadow
346:   c.fillStyle = 'rgba(0,0,0,.26)';
347:   c.beginPath(); c.ellipse(0, 1, 7.2, 2.4, 0, 0, Math.PI * 2); c.fill();
348: 
349:   // aura
350:   if (p.aura && !opts.noUi) {
351:     c.globalAlpha = .2 + Math.sin((t || 0) * 4) * .07;
352:     circle(c, 0, -14, 20, '#ffc84a');
353:     c.globalAlpha = 1;
354:   }
355: 
356:   // legs
357:   const swing = moving ? run * 3 : 0;
358:   if (!celeb) {
359:     px(c, -4, -9, 3, 7 + swing, skin);
360:     px(c, 1, -9, 3, 7 - swing, skin);
361:     px(c, -5, -3 + swing, 4, 3, '#15151d');
362:     px(c, 1, -3 - swing, 4, 3, '#15151d');
363:     // socks
364:     px(c, -4, -6, 3, 3, '#f1ead9');
365:     px(c, 1, -6, 3, 3, '#f1ead9');
366:   } else {
367:     px(c, -4, -9, 3, 8, skin);
368:     px(c, 1, -9, 3, 8, skin);
369:     px(c, -5, -2, 4, 3, '#15151d');
370:     px(c, 1, -2, 4, 3, '#15151d');
371:   }
372: 
373:   // shorts
374:   px(c, -5, -12 - bob, 10, 4, shorts);
375:   px(c, -5, -12 - bob, 10, 1, 'rgba(255,255,255,.15)');
376: 
377:   // torso
378:   px(c, -6, -21 - bob, 12, 9, jersey);
379:   px(c, -6, -21 - bob, 12, 1, 'rgba(255,255,255,.22)');
380:   px(c, -6, -15 - bob, 12, 1, accent);
381:   // sleeve cuffs
382:   px(c, -7, -20 - bob, 2, 4, accent);
383:   px(c, 5, -20 - bob, 2, 4, accent);
384:   // arms
385:   const armSwing = moving ? run * 2 : 0;
386:   px(c, -8, -20 - bob + armSwing, 2, 7, skin);
387:   px(c, 6, -20 - bob - armSwing, 2, 7, skin);
388:   if (gk) {
389:     px(c, -9, -14 - bob + armSwing, 3, 3, '#f7e8c8');
390:     px(c, 6, -14 - bob - armSwing, 3, 3, '#f7e8c8');
391:   }
392: 
393:   // head
394:   px(c, -4, -29 - bob, 8, 8, skin);
395:   px(c, -4, -29 - bob, 8, 1, 'rgba(255,255,255,.08)');
396:   // ears
397:   px(c, -5, -26 - bob, 1, 2, skin);
398:   px(c, 4, -26 - bob, 1, 2, skin);
399:   // eye
400:   if (facing >= 0) px(c, 2, -26 - bob, 1, 2, '#151019');
401:   else px(c, -3, -26 - bob, 1, 2, '#151019');
402:   // mouth
403:   px(c, facing >= 0 ? 2 : -3, -24 - bob, 2, 1, 'rgba(50,20,20,.55)');
404: 
405:   // hair
406:   if (p.isUser) {
407:     px(c, -4, -30 - bob, 8, 3, '#17100e');
408:     px(c, -5, -29 - bob, 1, 3, '#17100e');
409:     px(c, 4, -29 - bob, 1, 3, '#17100e');
410:     // curls
411:     circle(c, -4, -30 - bob, 1.6, '#17100e');
412:     circle(c, -1, -31 - bob, 1.8, '#17100e');
413:     circle(c, 2, -31 - bob, 1.8, '#17100e');
414:     circle(c, 4, -29 - bob, 1.5, '#17100e');
415:     // headband
416:     px(c, -4, -27.4 - bob, 8, 1.6, '#ffc84a');
417:     px(c, 4, -27 - bob, 1, 1, '#ffc84a');
418:   } else if (gk) {
419:     px(c, -4, -30 - bob, 8, 3, '#1a1a24');
420:     px(c, -5, -28 - bob, 1, 2, '#1a1a24');
421:     px(c, 4, -28 - bob, 1, 2, '#1a1a24');
422:   } else if ((p.num || 0) % 3 === 0) {
423:     px(c, -4, -30 - bob, 8, 2, hair);
424:     px(c, -5, -28 - bob, 1, 2, hair);
425:     px(c, 4, -28 - bob, 1, 2, hair);
426:   } else if ((p.num || 0) % 3 === 1) {
427:     px(c, -4, -30 - bob, 8, 3, hair);
428:     px(c, -5, -27 - bob, 1, 1, hair);
429:     px(c, 4, -27 - bob, 1, 1, hair);
430:   } else {
431:     px(c, -4, -30 - bob, 8, 2, hair);
432:     px(c, -4, -28 - bob, 8, 1, hair);
433:   }
434: 
435:   // tiny number / captain mark
436:   if (p.isUser) {
437:     px(c, -1, -19 - bob, 2, 1, '#0a0e19');
438:     px(c, -1, -17 - bob, 2, 1, '#0a0e19');
439:   }
440: 
441:   // selection marker
442:   if (p.isUser && !opts.noUi) {
443:     const pulse = .5 + Math.sin((t || 0) * 5) * .2;
444:     c.globalAlpha = .35 + pulse * .25;
445:     ring(c, 0, 1, 10.5, '#ffc84a', 1.5);
446:     c.globalAlpha = 1;
447:     // chevron
448:     const oy = -38 - bob + Math.sin((t || 0) * 4) * 1.2;
449:     c.fillStyle = '#ffc84a';
450:     c.beginPath(); c.moveTo(0, oy); c.lineTo(-3, oy - 4); c.lineTo(3, oy - 4); c.closePath(); c.fill();
451:     // name tag
452:     if (opts.tag !== false) {
453:       px(c, -17, oy - 12, 34, 7, 'rgba(8,13,25,.82)');
454:       text(c, 'CARLOS 10', 0, oy - 6, 5, '#ffc84a', 'center');
455:     }
456:   }
457: 
458:   // stun stars
459:   if (p.stun > 0) {
460:     for (let i = 0; i < 3; i++) {
461:       const a = (t || 0) * 5 + i * 2.1;
462:       px(c, Math.cos(a) * 8, -33 - bob + Math.sin(a) * 2, 2, 2, '#ffe28a');
463:     }
464:   }
465: 
466:   // celebration arms
467:   if (celeb) {
468:     px(c, -8, -27 - bob, 2, 8, skin);
469:     px(c, 6, -27 - bob, 2, 8, skin);
470:   }
471: 
472:   c.restore();
473: }
