475: export function drawBall(c, ball, t) {
476:   const x = Math.round(ball.x), y = Math.round(ball.y);
477:   // trail
478:   if (ball.trail && ball.trail.length) {
479:     for (let i = 0; i < ball.trail.length; i++) {
480:       const tr = ball.trail[i];
481:       const a = (i / ball.trail.length) * .32;
482:       circle(c, tr.x, tr.y, 1.5 + (i / ball.trail.length) * 2.2, ball.team === 0 ? `rgba(255,220,120,${a})` : `rgba(120,210,255,${a})`);
483:     }
484:   }
485:   // shadow
486:   c.fillStyle = 'rgba(0,0,0,.24)';
487:   c.beginPath(); c.ellipse(x + 1, y + 3, 4, 1.6, 0, 0, Math.PI * 2); c.fill();
488:   // ball
489:   circle(c, x, y, 3.6, '#f7f0df');
490:   circle(c, x, y, 3.6, 'rgba(255,255,255,.1)');
491:   const r = (ball.roll || 0);
492:   const spots = [[0, 0], [Math.cos(r) * 2, Math.sin(r) * 2], [Math.cos(r + 2.1) * 2, Math.sin(r + 2.1) * 2], [Math.cos(r + 4.2) * 2, Math.sin(r + 4.2) * 2]];
493:   for (let i = 0; i < spots.length; i++) {
494:     const [sx, sy] = spots[i];
495:     px(c, x + sx - .8, y + sy - .8, 1.6, 1.6, '#1c2333');
496:   }
497:   c.strokeStyle = 'rgba(20,25,40,.4)'; c.lineWidth = .8;
498:   c.beginPath(); c.arc(x, y, 3.6, 0, Math.PI * 2); c.stroke();
499: }
