505: export function drawMatchScene(c, match, t) {
506:   c.drawImage(getArenaBase(match.config.arena), 0, 0);
507:   drawArenaDynamic(c, match, t);
508: 
509:   if (match.cine) {
510:     drawCinematic(c, match, t);
511:     return;
512:   }
513: 
514:   // players sorted by feet y
515:   const players = [...match.home.players, ...match.away.players];
516:   players.sort((a, b) => a.y - b.y);
517:   for (const p of players) drawPlayer(c, p, t);
518: 
519:   // ball
520:   drawBall(c, match.ball, t);
521: 
522:   // charge ring + aim
523:   if (match.charge && match.charge.active) {
524:     const p = match.user;
525:     const q = match.charge.quality || 0;
526:     const col = q > .72 ? '#3ddc84' : q > .4 ? '#ffc84a' : '#ff5d6c';
527:     ring(c, p.x, p.y, 15 + Math.sin(t * 10) * 1.5, col, 1.5);
528:     c.globalAlpha = .8;
529:     line(c, p.x, p.y, 596, 196 + (match.charge.aimY || 0) * 26, col, 1);
530:     c.globalAlpha = .25;
531:     line(c, p.x, p.y - 1, 596, 196 + (match.charge.aimY || 0) * 26, col, 4);
532:     c.globalAlpha = 1;
533:   }
534: 
535:   // effects
536:   for (const fx of match.effects || []) {
537:     const a = clamp(fx.life / fx.max, 0, 1);
538:     if (fx.kind === 'confetti') {
539:       px(c, fx.x, fx.y, fx.size, fx.size * 1.6, fx.color);
540:     } else if (fx.kind === 'dust') {
541:       c.globalAlpha = a * .5;
542:       circle(c, fx.x, fx.y, fx.size * (1.4 - a * .4), fx.color);
543:       c.globalAlpha = 1;
544:     } else if (fx.kind === 'spark') {
545:       c.globalAlpha = a;
546:       line(c, fx.x, fx.y, fx.x - fx.vx * .04, fx.y - fx.vy * .04, fx.color, 1.4);
547:       c.globalAlpha = 1;
548:     } else if (fx.kind === 'text') {
549:       c.globalAlpha = a;
550:       text(c, fx.text, fx.x, fx.y, fx.size || 8, fx.color, 'center', 'Press Start 2P');
551:       c.globalAlpha = 1;
552:     }
553:   }
554: 
555:   // goal / halftime tints
556:   if (match.state === 'goal') {
557:     const flash = Math.max(0, 1 - match.stateT * 1.8);
558:     c.fillStyle = `rgba(255,255,255,${flash * .32})`;
559:     c.fillRect(0, 0, W, H);
560:     drawCelebrationConfetti(c, match, t);
561:   }
562: 
563:   if (match.tension >= 100) {
564:     const p = match.user;
565:     c.globalAlpha = .1 + Math.sin(t * 6) * .05;
566:     circle(c, p.x, p.y - 12, 26, '#ffc84a');
567:     c.globalAlpha = 1;
568:   }
569: 
570:   // final flash
571:   if (match.flash > 0) {
572:     c.fillStyle = `rgba(255,255,255,${clamp(match.flash, 0, .7)})`;
573:     c.fillRect(0, 0, W, H);
574:   }
575: }
