577: function drawArenaDynamic(c, match, t) {
578:   const arena = match.config.arena;
579:   const rnd = mulberry32(arena === 'final' ? 71 : arena === 'club' ? 41 : 23);
580:   const standH = 74;
581:   // crowd flashes
582:   for (let i = 0; i < 10; i++) {
583:     const x = rnd() * W;
584:     const y = 10 + rnd() * 52;
585:     const on = Math.sin(t * (1.5 + i * .35) + i * 2.7) > .94;
586:     if (on) px(c, x, y, 2, 2, 'rgba(255,255,255,.95)');
587:   }
588:   // flags
589:   for (let i = 0; i < 5; i++) {
590:     const x = 24 + i * 140;
591:     const y = 20 + (i % 2) * 8;
592:     const wav = Math.sin(t * 2.4 + i) * 2;
593:     px(c, x, y, 20, 8, i % 2 ? (arena === 'final' ? '#ffc84a' : '#3aa7ff') : (arena === 'final' ? '#3ddc84' : '#ffc84a'));
594:     px(c, x + 20, y + wav, 7, 3, i % 2 ? (arena === 'final' ? '#ffc84a' : '#3aa7ff') : (arena === 'final' ? '#3ddc84' : '#ffc84a'));
595:   }
596:   // corner flags wave
597:   if (Math.sin(t * 3) > 0) {
598:     px(c, FIELD.r + 1, FIELD.t - 8, 7, 4, '#ffc84a');
599:   }
600:   // ambient confetti at final
601:   if (arena === 'final') {
602:     for (let i = 0; i < 18; i++) {
603:       const x = (i * 41 + t * 9) % W;
604:       const y = (i * 29 + t * 18) % H;
605:       px(c, x, y, 1, 2, ['#ffc84a', '#3ddc84', '#3aa7ff', '#ff5d6c', '#f7e8c8'][i % 5]);
606:     }
607:   }
608:   // light beams
609:   if (arena === 'final') {
610:     c.save();
611:     c.globalAlpha = .05 + Math.sin(t * .7) * .012;
612:     c.fillStyle = '#fff4cf';
613:     c.beginPath(); c.moveTo(48, 8); c.lineTo(92, 8); c.lineTo(190, 320); c.lineTo(20, 320); c.closePath(); c.fill();
614:     c.beginPath(); c.moveTo(548, 8); c.lineTo(592, 8); c.lineTo(622, 320); c.lineTo(452, 320); c.closePath(); c.fill();
615:     c.restore();
616:   }
617:   // ball shadow on field? ball handles
618: }
