622:   for (let i = 0; i < 90; i++) {
623:     const x = (i * 73 + Math.sin(t * 3 + i) * 18 + t * 30) % W;
624:     const y = (i * 37 + t * 65 + Math.sin(t * 2 + i) * 20) % H;
