638: export function drawTrainingView(c, data, t) {
639:   drawScene(c, data.scene || 'beach_sunset', t);
640:   // vignette + bottom scrim
641:   const grad = c.createLinearGradient(0, 180, 0, 360);
642:   grad.addColorStop(0, 'rgba(5,8,16,0)');
643:   grad.addColorStop(1, 'rgba(5,8,16,.72)');
644:   c.fillStyle = grad; c.fillRect(0, 180, W, 180);
645: 
646:   const bx = 320;
647:   const ground = 306;
648:   // spotlight
649:   c.save();
650:   c.globalAlpha = .1 + Math.sin(t * 2) * .025;
651:   circle(c, bx, ground - 30, 90, '#fff1c2');
652:   c.restore();
653: 
654:   // coach silhouette
655:   drawCoach(c, 468, 312, t);
656: 
657:   // Carlos juggling
658:   const fake = {
659:     x: bx, y: ground, vx: 0, vy: 0, num: 10, team: 0, role: 'FW', isUser: true,
660:     kit: { color: '#ffc84a', accent: '#00a86b' }, anim: t,
661:     facing: 1, speed: 0
662:   };
663:   drawPlayer(c, fake, t, { scale: 1.75, tag: false });
664: 
665:   // ball arc
