  return;
 }
 if(d.type==='attack'){
   if(cmd==='shoot' && !this.canShoot(d.attacker)) return;
   if(!['dribble','pass','shoot'].includes(cmd)) return;
 } else {
   if(!['tackle','contain','slide'].includes(cmd)) return;
 }
 d.command=cmd; d.phase='meter'; d.meter=0; d.dir=1; d.speed=1.15+rand(0,.5);
 this.ui.duelChoosePhase(); this.audio.sfx('ui');
}
updateDuel(dt){
 const d=this.duel; if(!d)return;
 if(d.phase==='choose'){
   const map=['dribble','pass','shoot','special']; // 1..4
   ...
   if(d.type==='defense') map=['tackle','contain','slide','special'];
   for i ...
   return;
 }
 if(d.phase==='meter'){
