if(pen.turn==='home'){
 const keeper=['left','center','right'][Math.floor(Math.random()*3)];
 const saved=Math.random()<0.18;
 this.ui.animatePenalty(dir,keeper,saved,false);
 this.ui.penaltyResult(saved?'SAVED!':'GOAL!');
 pen.wait=1.25; pen.after=()=>{ if(!saved) pen.home++; pen.homeKicks++; this.afterPenaltyKick(); };
} else {
