+  /* ------------------------------------------------------------------ */
+  /* STORY SCRIPTS                                                       */
+  /* ------------------------------------------------------------------ */
+
+  checkScripts() {
+    const minute = this.minute;
+    for (const s of this.config.scripts || []) {
+      if (this.scripted.has(s) || minute < s.minute) continue;
+      this.scripted.add(s);
+      if (s.type === 'drive') {
