+        size: rand(1.5, 3.5), color: colors[i % colors.length],
+        life, max: life
+      });
+    }
+  }
+
+  addText(text, x, y, color, size = 8, life = 1.2) {
+    this.effects.push({ kind: 'text', text, x, y, vx: 0, vy: -26, size, color, life, max: life });
+  }
+
+  updateEffects(dt) {
+    for (const fx of this.effects) {
