  beginTraining() {
    const cfg=this.chapter.training;
    this.mode='training'; this.showScreen('training','training');
    const attempts=cfg.attempts||8;
    this.training={...cfg, hits:0, attemptsDone:0, combo:0, bestCombo:0, needle:0, dir:1, targetCenter:.5, zone:cfg.zone||.24, hitFlash:0, hitText:'', done:false, ballHeight:0};
    $('training-chip').textContent = `TRAINING · ${cfg.title}`; ...
    training-made text 0; next small...
    combo text 'COMBO x0';
    this.setTrainingTarget();
    this.audio.setCrowd(0);
    this.setMusic('training');
    this.audio.sfx('select');
  }

  setTrainingTarget() {
    const t=this.training; const half=t.zone/2;
    t.targetCenter = rand... (use Math.random)
    const el=$('training-target'); el.style.left=`${(t.targetCenter-half)*100}%`; el.style.width=`${t.zone*100}%`;
  }

  updateTraining(dt) {
    const t=this.training; if(!t||t.done)return;
    t.needle += t.dir*dt*(t.speed||1.1)*0.9;
    if(t.needle>1){t.needle=1;t.dir=-1}
    if(t.needle<0){t.needle=0;t.dir=1}
    t.ballHeight=(Math.sin(this.time*5)+1)/2;
    t.hitFlash=Math.max(0,t.hitFlash-dt*2.4);
    $('training-needle').style.left = `${t.needle*100}%`;
    if(this.input.take('shoot')||this.input.take('confirm')) this.hitTraining();
  }

  hitTraining() {
    const t=this.training; if(!t||t.done)return;
    const hit = Math.abs(t.needle - t.targetCenter) <= t.zone/2;
    t.attemptsDone++;
    t.ballHeight=1;
    t.hitFlash=1;
    if(hit){t.hits++;t.combo++;t.bestCombo=Math.max(...);t.hitText=['NICE!','SWEET!','PERFECT!'][...]}
    else {t.combo=0;t.hitText='MISS'}
    $('training-made').textContent=t.hits;
    $('training-combo').textContent=`COMBO x${t.combo}`;
    const toast=$('training-toast'); toast.textContent=t.hitText; toast.classList.remove('show'); void toast.offsetWidth; toast.classList.add('show');
    this.audio.sfx(hit?'pass':'lose-duel');
    if(t.attemptsDone>=t.attempts){t.done=true; setTimeout(()=>this.finishTraining(),800); return}
    this.setTrainingTarget();
  }

  finishTraining() {
    if(this.screen!=='training')return;
    const t=this.training; const pairs=Math.floor((t?.hits||0)/2); const amount=pairs*2;
    this.trainingResult = t ? {hits:t.hits, stat:t.stat, bonus:amount, attempts:t.attempts} : null;
    this.audio.sfx('win');
    this.showPrematch();
  }

  skipTraining() {
    const t=this.training; if(t) t.done=true;
    this.trainingResult={hits:0,stat:this.chapter.training.stat,bonus:0,attempts:this.chapter.training.attempts};
    this.showPrematch();
  }
